package com.hbm.satellite.cargo.client;
import com.hbm.client.model.*;import com.hbm.satellite.cargo.SatelliteDockBlockEntity;import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;import org.joml.Matrix4f;
/** Original RenderDecoBlock two180Z rotations cancel to exact origin .5,0,.5; originalnoSmooth cargo_pad. */
public final class SatelliteDockRenderer implements BlockEntityRenderer<SatelliteDockBlockEntity>{
 public SatelliteDockRenderer(BlockEntityRendererProvider.Context context){}static WavefrontMesh mesh(){return LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),ResourceLocation.parse("hbm:models/machines/cargo_pad.obj"));}static void model(PoseStack poses,MultiBufferSource buffers,int light,int overlay){LegacyObjRenderer.render(mesh(),poses,buffers.getBuffer(RenderType.entityCutoutNoCull(ResourceLocation.parse("hbm:textures/models/machines/cargo_pad.png"))),light,overlay,-1,LegacyObjRenderer.Convention.HFR_FLAT,face->true);}
 @Override public void render(SatelliteDockBlockEntity dock,float partial,PoseStack poses,MultiBufferSource buffers,int light,int overlay){LegacyContactShadows.render(dock,mesh(),new Matrix4f().translation(.5F,0,.5F),poses,buffers);poses.pushPose();poses.translate(.5,0,.5);model(poses,buffers,light,overlay);poses.popPose();}@Override public boolean shouldRenderOffScreen(SatelliteDockBlockEntity dock){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(SatelliteDockBlockEntity dock){var pos=dock.getBlockPos();return new AABB(pos.getX()-1,pos.getY(),pos.getZ()-1,pos.getX()+2,pos.getY()+1,pos.getZ()+2);}
}
